// What the DSi-mode ROM shows when the machine gives it only 4 MB of RAM (a DS, or an emulator that is not in DSi mode): a message instead of a blank red screen.
// Called from hw/crt0.s before anything else is set up (only the stack exists), so it uses nothing but constants and the stack. VRAM bank A is mapped as a bitmap and shown as is.
typedef unsigned short u16; typedef unsigned int u32; typedef unsigned char u8;
static const u8 fnt[][5]={ {0,0,0,0,0},{0x7E,0x11,0x11,0x11,0x7E},{0x7F,0x49,0x49,0x49,0x36},{0x3E,0x41,0x41,0x41,0x22},{0x7F,0x41,0x41,0x22,0x1C},{0x7F,0x49,0x49,0x49,0x41},{0x7F,0x09,0x09,0x09,0x01},{0x3E,0x41,0x49,0x49,0x7A},{0x7F,0x08,0x08,0x08,0x7F},{0,0x41,0x7F,0x41,0},{0x20,0x40,0x41,0x3F,0x01},{0x7F,0x08,0x14,0x22,0x41},{0x7F,0x40,0x40,0x40,0x40},{0x7F,0x02,0x0C,0x02,0x7F},{0x7F,0x04,0x08,0x10,0x7F},{0x3E,0x41,0x41,0x41,0x3E},{0x7F,0x09,0x09,0x09,0x06},{0x3E,0x41,0x51,0x21,0x5E},{0x7F,0x09,0x19,0x29,0x46},{0x46,0x49,0x49,0x49,0x31},{0x01,0x01,0x7F,0x01,0x01},{0x3F,0x40,0x40,0x40,0x3F},{0x1F,0x20,0x40,0x20,0x1F},{0x3F,0x40,0x38,0x40,0x3F},{0x63,0x14,0x08,0x14,0x63},{0x07,0x08,0x70,0x08,0x07},{0x61,0x51,0x49,0x45,0x43},   // blank, A..Z
 {0x3E,0x51,0x49,0x45,0x3E},{0,0x42,0x7F,0x40,0},{0x42,0x61,0x51,0x49,0x46},{0x21,0x41,0x45,0x4B,0x31},{0x18,0x14,0x12,0x7F,0x10},{0x27,0x45,0x45,0x45,0x39},{0x3C,0x4A,0x49,0x49,0x30},{0x01,0x71,0x09,0x05,0x03},{0x36,0x49,0x49,0x49,0x36},{0x06,0x49,0x49,0x29,0x1E},   // 0..9
 {0,0x60,0x60,0,0},{0x08,0x08,0x08,0x08,0x08},{0x40,0x40,0x40,0x40,0x40},{0,0x1C,0x22,0x41,0},{0,0x41,0x22,0x1C,0},{0x20,0x10,0x08,0x04,0x02},{0,0x50,0x30,0,0} };   // . - _ ( ) / ,
static int glyph(char c){ if(c>='A'&&c<='Z') return 1+c-'A'; if(c>='0'&&c<='9') return 27+c-'0'; switch(c){ case '.': return 37; case '-': return 38; case '_': return 39; case '(': return 40; case ')': return 41; case '/': return 42; case ',': return 43; } return 0; }
static void text(volatile u16*fb,int x,int y,const char*s,int sc,u16 col){ for(;*s;s++,x+=6*sc){ const u8*g=fnt[glyph(*s)]; for(int cx=0;cx<5;cx++) for(int cy=0;cy<7;cy++) if(g[cx]>>cy&1) for(int a=0;a<sc;a++) for(int b=0;b<sc;b++){ int px=x+cx*sc+a, py=y+cy*sc+b; if(px<256&&py<192) fb[py*256+px]=col; } } }
void __attribute__((noreturn)) ramfail(void){
    *(volatile u16*)0x04000304=0x0203;        // both screens on, the picture on the lower one
    *(volatile u8*)0x04000240=0x80;           // VRAM bank A at 0x06800000
    *(volatile u32*)0x04000000=0x00020000;    // display VRAM bank A as a bitmap
    volatile u16*fb=(volatile u16*)0x06800000; for(int i=0;i<256*192;i++) fb[i]=0x8000|(4<<10)|(2<<5)|2;
    text(fb,10,12,"NEEDS DSI MODE",2,0x8000|0x7FFF);
    text(fb,10,48,"THIS ROM NEEDS 16 MB OF RAM.",1,0x8000|0x03FF);
    text(fb,10,60,"YOUR PLAYER GIVES ONLY 4 MB, SO IT",1,0x8000|0x7FFF);
    text(fb,10,70,"IS NOT RUNNING IN DSI MODE.",1,0x8000|0x7FFF);
    text(fb,10,96,"PLAY ONE OF THESE INSTEAD:",1,0x8000|0x03FF);
    text(fb,10,108,"GODGUY_DSI.NDS (RUNS ANYWHERE)",1,0x8000|0x03E0);
    text(fb,10,118,"GODGUY_HW.NDS (PLAIN DS)",1,0x8000|0x03E0);
    text(fb,10,142,"OR USE A REAL DSI, OR AN EMULATOR",1,0x8000|0x7FFF);
    text(fb,10,152,"WITH DSI MODE TURNED ON (MELONDS).",1,0x8000|0x7FFF);
    for(;;){} }
